  // Calculate the overlap on each axis to determine the collision face
  const overlapX = Math.min(
    (state.ball.x + state.ball.r) - brick.x, // overlap left
    (brick.x + brick.w) - (state.ball.x - state.ball.r) // overlap right
  );
  const overlapY = Math.min(
    (state.ball.y + state.ball.r) - brick.y, // overlap top
    (brick.x + brick.h) - (state.ball.y - state.ball.r) // overlap bottom
  );

  // This is a simplification. A more robust way is to use the distance
  // from the ball center to the brick boundaries.
  const distLeft = (state.ball.x) - brick.x;
  const distRight = (brick.x + brick.w) - (state.ball.x);
  const distTop = (state.ball.y) - brick.y;
  const distBottom = (brick.y + brick.h) - (state.ball.y);

  const minX = Math.min(distLeft, distRight);
  const minY = Math.min(distTop, distBottom);

  if (minX < minY) {
    // Side hit
    state.ball.vx = -Math.sign(state.ball.vx);
    // Push ball out of brick to prevent sticking
    state.ball.x += (state.ball.vx > 0 ? state.ball.r : -state.ball.r) * 0.1;
  } else {
    // Top/Bottom hit
    state.ball.vy = -Math.sign(state.ball.vy);
    // Push ball out of brick
    state.ball.y += (state.ball.vy > 0 ? state.ball.r : -state.ball.r) * 0.1;
  }
}

